  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'CLAS', 'KERNEL_INTERNAL_NAME', '$TMP', '', 'ABC', '', '', '', 'E');`);
  insert.push(`INSERT INTO reposrc ('PROGNAME', 'DATA') VALUES ('KERNEL_INTERNAL_NAME                    ', 'CLASS kernel_internal_name DEFINITION PUBLIC.
  PUBLIC SECTION.
    CLASS-METHODS internal_to_rtti
      IMPORTING
        iv_internal    TYPE string
      RETURNING
        VALUE(rv_rtti) TYPE string.

    CLASS-METHODS rtti_to_internal
      IMPORTING
        iv_rtti            TYPE string
      RETURNING
        VALUE(rv_internal) TYPE string.
ENDCLASS.

CLASS kernel_internal_name IMPLEMENTATION.

  METHOD internal_to_rtti.
    rv_rtti = iv_internal.
    IF rv_rtti CP ''*CLAS-*''.
      REPLACE FIRST OCCURRENCE OF ''CLAS-'' IN rv_rtti WITH ''\\CLASS#POOL=''.
      REPLACE FIRST OCCURRENCE OF ''-'' IN rv_rtti WITH ''\\CLASS=''.
      REPLACE FIRST OCCURRENCE OF ''#'' IN rv_rtti WITH ''-''.
    ELSE.
      rv_rtti = ''\\CLASS='' && rv_rtti.
    ENDIF.
  ENDMETHOD.

  METHOD rtti_to_internal.
    rv_internal = iv_rtti.
    IF rv_internal CP ''\\CLASS=*''.
      REPLACE FIRST OCCURRENCE OF ''\\CLASS='' IN rv_internal WITH ''''.
    ELSEIF rv_internal CP ''\\CLASS-POOL=*''.
      REPLACE FIRST OCCURRENCE OF ''\\CLASS-POOL='' IN rv_internal WITH ''CLAS-''.
      REPLACE FIRST OCCURRENCE OF ''\\CLASS='' IN rv_internal WITH ''-''.
      REPLACE FIRST OCCURRENCE OF ''\\INTERFACE='' IN rv_internal WITH ''-''.
    ENDIF.
  ENDMETHOD.

ENDCLASS.');`);
  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'CLAS', 'KERNEL_CREATE_DATA_HANDLE', '$TMP', '', 'ABC', '', '', '', 'E');`);
  insert.push(`INSERT INTO reposrc ('PROGNAME', 'DATA') VALUES ('KERNEL_CREATE_DATA_HANDLE               ', 'CLASS kernel_create_data_handle DEFINITION PUBLIC.
  PUBLIC SECTION.
    CLASS-METHODS call
      IMPORTING
        handle        TYPE REF TO cl_abap_datadescr
        allow_generic TYPE abap_bool OPTIONAL
      CHANGING
        dref          TYPE REF TO any.
  PRIVATE SECTION.
    CLASS-METHODS elem
      IMPORTING
        handle TYPE REF TO cl_abap_datadescr
      CHANGING
        dref   TYPE REF TO any.
    CLASS-METHODS struct
      IMPORTING
        handle TYPE REF TO cl_abap_datadescr
      CHANGING
        dref   TYPE REF TO any.
    CLASS-METHODS table
      IMPORTING
        handle TYPE REF TO cl_abap_datadescr
      CHANGING
        dref   TYPE REF TO any.
    CLASS-METHODS ref
      IMPORTING
        handle TYPE REF TO cl_abap_datadescr
      CHANGING
        dref   TYPE REF TO any.
ENDCLASS.

CLASS kernel_create_data_handle IMPLEMENTATION.

  METHOD call.
    IF handle IS NOT BOUND.
      RAISE EXCEPTION TYPE cx_sy_ref_is_initial.
    ENDIF.

    IF handle->type_kind = cl_abap_typedescr=>typekind_data
        AND allow_generic = abap_false.
      RAISE EXCEPTION TYPE cx_sy_create_data_error.
    ENDIF.

    WRITE ''@KERNEL if (dref.constructor.name === "FieldSymbol") {''.
    WRITE ''@KERNEL   dref = dref.getPointer();''.
    WRITE ''@KERNEL }''.

    CASE handle->kind.
      WHEN cl_abap_typedescr=>kind_elem.
        elem( EXPORTING handle = handle
              CHANGING dref    = dref ).
      WHEN cl_abap_typedescr=>kind_struct.
        struct( EXPORTING handle = handle
                CHANGING dref    = dref ).
      WHEN cl_abap_typedescr=>kind_table.
        table( EXPORTING handle = handle
               CHANGING dref    = dref ).
      WHEN cl_abap_typedescr=>kind_ref.
        ref( EXPORTING handle = handle
             CHANGING dref    = dref ).
      WHEN OTHERS.
        WRITE ''@KERNEL console.dir(handle);''.
        ASSERT 1 = ''todo''.
    ENDCASE.
  ENDMETHOD.

  METHOD ref.
    DATA lo_refdescr      TYPE REF TO cl_abap_refdescr.
    DATA lo_datadescr     TYPE REF TO cl_abap_datadescr.
    DATA lo_classdescr    TYPE REF TO cl_abap_classdescr.
    DATA field            TYPE REF TO data.
    DATA lv_relative_name TYPE string.
    DATA lv_absolute_name TYPE string.

    lo_refdescr ?= handle.

    CASE lo_refdescr->type_kind.
      WHEN cl_abap_typedescr=>typekind_oref.
        lo_classdescr ?= lo_refdescr->get_referenced_type( ).
        " todo, call the methods in class "kernel_internal_name" ?
        lv_relative_name = lo_classdescr->relative_name.
        lv_absolute_name = lo_classdescr->absolute_name.
        WRITE ''@KERNEL dref.assign(new abap.types.ABAPObject({"qualifiedName": lv_relative_name.get(), "RTTIName": lv_absolute_name.get()}));''.
      WHEN OTHERS.
        lo_datadescr ?= lo_refdescr->get_referenced_type( ).
        call(
          EXPORTING
            handle        = lo_datadescr
            allow_generic = abap_true
          CHANGING
            dref          = field ).

        WRITE ''@KERNEL dref.assign(new abap.types.DataReference(field.getPointer()));''.
    ENDCASE.
  ENDMETHOD.

  METHOD struct.
    DATA lo_struct     TYPE REF TO cl_abap_structdescr.
    DATA lt_components TYPE cl_abap_structdescr=>component_table.
    DATA field         TYPE REF TO data.
    DATA lv_name       TYPE string.
    DATA lv_suffix     TYPE string.

    FIELD-SYMBOLS <ls_component> LIKE LINE OF lt_components.

    lo_struct ?= handle.
    lt_components = lo_struct->get_components( ).
    WRITE ''@KERNEL let obj = {};''.
    WRITE ''@KERNEL let suffix = {};''.
    WRITE ''@KERNEL let asInclude = {};''.
    LOOP AT lt_components ASSIGNING <ls_component>.
*      WRITE ''@KERNEL console.dir(ls_component.get().name);''.
      call(
        EXPORTING
          handle = lo_struct->get_component_type( <ls_component>-name )
        CHANGING
          dref   = field ).
      lv_name = to_lower( <ls_component>-name ).
      WRITE ''@KERNEL obj[lv_name.get()] = field.getPointer();''.
      IF <ls_component>-as_include = abap_true.
        WRITE ''@KERNEL asInclude[lv_name.get()] = true;''.
      ENDIF.
      IF <ls_component>-suffix IS NOT INITIAL.
        lv_suffix = to_lower( <ls_component>-suffix ).
        WRITE ''@KERNEL suffix[lv_name.get()] = lv_suffix.get();''.
      ENDIF.
    ENDLOOP.
    WRITE ''@KERNEL dref.assign(new abap.types.Structure(obj, lo_struct.get().internal_qualified_name.get(), lo_struct.get().internal_ddic_name.get(), suffix, asInclude));''.
  ENDMETHOD.

  METHOD table.
    DATA lo_table     TYPE REF TO cl_abap_tabledescr.
    DATA lt_keys      TYPE abap_table_keydescr_tab.
    DATA lv_component TYPE string.
    DATA field        TYPE REF TO data.

    FIELD-SYMBOLS <ls_key> LIKE LINE OF lt_keys.

    lo_table ?= handle.

    call(
      EXPORTING
        handle = lo_table->get_table_line_type( )
      CHANGING
        dref   = field ).

    WRITE ''@KERNEL let options = {primaryKey: undefined, keyType: "DEFAULT", withHeader: false};''.
    WRITE ''@KERNEL options.primaryKey = {name: "primary_key", type: "STANDARD", keyFields: [], isUnique: false};''.

* todo, handle secondary keys,
    lt_keys = lo_table->get_keys( ).
    LOOP AT lt_keys ASSIGNING <ls_key> WHERE is_primary = abap_true.
      IF <ls_key>-access_kind = cl_abap_tabledescr=>tablekind_sorted.
        WRITE ''@KERNEL options.primaryKey.type = "SORTED";''.
      ELSEIF <ls_key>-access_kind = cl_abap_tabledescr=>tablekind_hashed.
        WRITE ''@KERNEL options.primaryKey.type = "HASHED";''.
      ENDIF.
      IF <ls_key>-is_unique = abap_true.
        WRITE ''@KERNEL options.primaryKey.isUnique = true;''.
      ENDIF.
      LOOP AT <ls_key>-components INTO lv_component.
        WRITE ''@KERNEL options.primaryKey.keyFields.push(lv_component.get().toLowerCase());''.
      ENDLOOP.
    ENDLOOP.

    WRITE ''@KERNEL dref.assign(abap.types.TableFactory.construct(field.getPointer(), options));''.
  ENDMETHOD.

  METHOD elem.
    DATA lv_half TYPE i.
    CASE handle->type_kind.
      WHEN cl_abap_typedescr=>typekind_data.
        WRITE ''@KERNEL dref.assign(new abap.types.Character(4));''.
      WHEN cl_abap_typedescr=>typekind_float.
        CREATE DATA dref TYPE f.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_string.
        CREATE DATA dref TYPE string.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_xstring.
        CREATE DATA dref TYPE xstring.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_int.
        CREATE DATA dref TYPE i.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_utclong.
        CREATE DATA dref TYPE utclong.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_date.
        CREATE DATA dref TYPE d.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_hex.
        CREATE DATA dref TYPE x LENGTH handle->length.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_packed.
        CREATE DATA dref TYPE p LENGTH handle->length DECIMALS handle->decimals.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_char.
        lv_half = handle->length / 2.
        CREATE DATA dref TYPE c LENGTH lv_half.
        WRITE ''@KERNEL dref.getPointer().extra = {"qualifiedName": handle.get().internal_qualified_name};''.
      WHEN cl_abap_typedescr=>typekind_num.
        lv_half = handle->length / 2.
        CREATE DATA dref TYPE n LENGTH lv_half.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_time.
        CREATE DATA dref TYPE t.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_int8.
        CREATE DATA dref TYPE int8.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_decfloat16.
        CREATE DATA dref TYPE decfloat16.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN cl_abap_typedescr=>typekind_decfloat34.
        CREATE DATA dref TYPE decfloat34.
        WRITE ''@KERNEL dref.getPointer().qualifiedName = handle.get().internal_qualified_name;''.
      WHEN OTHERS.
        WRITE ''@KERNEL console.dir(handle);''.
        ASSERT 1 = ''todo''.
    ENDCASE.
  ENDMETHOD.

ENDCLASS.
');`);
  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'CLAS', 'KERNEL_CALL', '$TMP', '', 'ABC', '', '', '', 'E');`);
  insert.push(`INSERT INTO reposrc ('PROGNAME', 'DATA') VALUES ('KERNEL_CALL                             ', 'CLASS kernel_call DEFINITION PUBLIC.
* handling of ABAP statement CALL
  PUBLIC SECTION.
    CLASS-METHODS call
      IMPORTING
        input TYPE any.
  PRIVATE SECTION.
ENDCLASS.

CLASS kernel_call IMPLEMENTATION.

  METHOD call.

    DATA uuid  TYPE sysuuid_x16.
    DATA name  TYPE string.
    DATA magic TYPE d.

    WRITE ''@KERNEL name.set(INPUT.name);''.

    IF name = ''RFCControl''.
      uuid = cl_system_uuid=>if_system_uuid_static~create_uuid_x16( ).
      WRITE ''@KERNEL INPUT.uuid.set(uuid);''.
    ELSEIF name = ''CONVERSION_EXIT_ALPHA_INPUT''.
      WRITE ''@KERNEL magic = INPUT.output''.
      CALL FUNCTION ''CONVERSION_EXIT_ALPHA_INPUT''
        EXPORTING
          input  = input
        IMPORTING
          output = magic.
    ELSEIF name = ''zcsa/installed_languages''.
* todo, this is all wrong as the "name" overlaps
      RETURN.
    ELSE.
      WRITE / |Unknown kernel function: { name }|.
      ASSERT 1 = 2.
    ENDIF.

  ENDMETHOD.

ENDCLASS.');`);
  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'CLAS', 'KERNEL_AUTHORITY_CHECK', '$TMP', '', 'ABC', '', '', '', 'E');`);
  insert.push(`INSERT INTO reposrc ('PROGNAME', 'DATA') VALUES ('KERNEL_AUTHORITY_CHECK                  ', 'CLASS kernel_authority_check DEFINITION PUBLIC.
  PUBLIC SECTION.
    CLASS-METHODS call
      IMPORTING
        object TYPE csequence OPTIONAL
        user   TYPE csequence OPTIONAL
        fields TYPE any OPTIONAL.

    CLASS-METHODS restrict
      IMPORTING authorizations TYPE cl_aunit_auth_check_types_def=>user_role_authorizations.

    CLASS-METHODS reset.

    CLASS-METHODS get_execution_status
      EXPORTING
        passed_execution TYPE cl_aunit_auth_check_types_def=>auth_ctxtset_msgs
        failed_execution TYPE cl_aunit_auth_check_types_def=>auth_ctxtset_msgs.
  PRIVATE SECTION.
    CLASS-DATA gv_restricted TYPE abap_bool.
    CLASS-DATA gt_authorizations TYPE cl_aunit_auth_check_types_def=>user_role_authorizations.
    CLASS-DATA gt_passed TYPE cl_aunit_auth_check_types_def=>auth_ctxtset_msgs.
    CLASS-DATA gt_failed TYPE cl_aunit_auth_check_types_def=>auth_ctxtset_msgs.

    CLASS-METHODS is_authorized
      IMPORTING
        object                TYPE csequence
        user                  TYPE csequence
        authorization         TYPE cl_aunit_auth_check_types_def=>authorization
      RETURNING VALUE(result) TYPE abap_bool.

    CLASS-METHODS authorization_matches
      IMPORTING
        configured            TYPE cl_aunit_auth_check_types_def=>authorization
        requested             TYPE cl_aunit_auth_check_types_def=>authorization
      RETURNING VALUE(result) TYPE abap_bool.
ENDCLASS.

CLASS kernel_authority_check IMPLEMENTATION.

  METHOD call.
    DATA lv_user TYPE sy-uname.
    DATA lv_subrc TYPE sysubrc.
    DATA ls_log TYPE cl_aunit_auth_check_types_def=>auth_ctxtset_msg.
    DATA authorization TYPE cl_aunit_auth_check_types_def=>authorization.

    WRITE ''@KERNEL if (INPUT.fields) {''.
    WRITE ''@KERNEL   for (const inputField of INPUT.fields) {''.
    WRITE ''@KERNEL     if (inputField.dummy === true) continue;''.
    WRITE ''@KERNEL     const authField = authorization.getRowType().clone();''.
    WRITE ''@KERNEL     authField.get().fieldname.set(inputField.id);''.
    WRITE ''@KERNEL     const interval = authField.get().fieldvalues.getRowType().clone();''.
    WRITE ''@KERNEL     interval.get().lower_value.set(inputField.field);''.
    WRITE ''@KERNEL     authField.get().fieldvalues.append(interval);''.
    WRITE ''@KERNEL     abap.statements.insertInternal({data: authField, table: authorization});''.
    WRITE ''@KERNEL   }''.
    WRITE ''@KERNEL }''.

    lv_user = user.
    IF lv_user IS INITIAL.
      lv_user = sy-uname.
    ENDIF.

    ls_log-object = object.
    ls_log-user = lv_user.
    ls_log-authorizations = authorization.

    IF gv_restricted = abap_false OR is_authorized(
        object        = object
        user          = lv_user
        authorization = authorization ) = abap_true.
      lv_subrc = 0.
      ls_log-description = ''Authorization check passed''.
      APPEND ls_log TO gt_passed.
    ELSE.
      lv_subrc = 4.
      ls_log-description = ''Authorization check failed''.
      APPEND ls_log TO gt_failed.
    ENDIF.
    sy-subrc = lv_subrc.
  ENDMETHOD.

  METHOD restrict.
    gt_authorizations = authorizations.
    gv_restricted = abap_true.
    CLEAR gt_passed.
    CLEAR gt_failed.
  ENDMETHOD.

  METHOD reset.
    CLEAR gv_restricted.
    CLEAR gt_authorizations.
    CLEAR gt_passed.
    CLEAR gt_failed.
  ENDMETHOD.

  METHOD get_execution_status.
    passed_execution = gt_passed.
    failed_execution = gt_failed.
  ENDMETHOD.

  METHOD is_authorized.
    DATA ls_user_auth LIKE LINE OF gt_authorizations.
    DATA ls_object TYPE cl_aunit_auth_check_types_def=>authorizations_for_object.
    DATA lt_users TYPE cl_aunit_auth_check_types_def=>auth_users.
    DATA ls_configured TYPE cl_aunit_auth_check_types_def=>authorization.

    result = abap_false.
    IF object IS INITIAL.
      RETURN.
    ENDIF.

    LOOP AT gt_authorizations INTO ls_user_auth.
      lt_users = ls_user_auth-users.
      IF lt_users IS NOT INITIAL.
        READ TABLE lt_users WITH KEY table_line = user TRANSPORTING NO FIELDS.
        IF sy-subrc <> 0.
          CONTINUE.
        ENDIF.
      ENDIF.

      LOOP AT ls_user_auth-role_authorizations INTO ls_object WHERE object = object.
        IF ls_object-authorizations IS INITIAL.
          result = abap_true.
          RETURN.
        ENDIF.
        LOOP AT ls_object-authorizations INTO ls_configured.
          IF authorization_matches(
              configured = ls_configured
              requested  = authorization ) = abap_true.
            result = abap_true.
            RETURN.
          ENDIF.
        ENDLOOP.
      ENDLOOP.
    ENDLOOP.
  ENDMETHOD.

  METHOD authorization_matches.
    DATA ls_requested LIKE LINE OF requested.
    DATA ls_configured LIKE LINE OF configured.
    DATA ls_requested_value LIKE LINE OF ls_requested-fieldvalues.
    DATA ls_configured_value LIKE LINE OF ls_configured-fieldvalues.
    DATA lv_value TYPE c LENGTH 40.
    DATA lv_matched TYPE abap_bool.

    result = abap_true.
    IF configured IS INITIAL.
      RETURN.
    ENDIF.

    LOOP AT requested INTO ls_requested.
      IF ls_requested-fieldvalues IS INITIAL.
        CONTINUE.
      ENDIF.
      READ TABLE configured INTO ls_configured
        WITH TABLE KEY primary_key COMPONENTS fieldname = ls_requested-fieldname.
      IF sy-subrc <> 0.
        result = abap_false.
        RETURN.
      ENDIF.

      LOOP AT ls_requested-fieldvalues INTO ls_requested_value.
        lv_value = ls_requested_value-lower_value.
        lv_matched = abap_false.
        LOOP AT ls_configured-fieldvalues INTO ls_configured_value.
          IF ls_configured_value-lower_value = ''*''
              OR ( ls_configured_value-upper_value IS INITIAL
                AND ( ( ls_configured_value-lower_value CS ''*''
                    AND lv_value CP ls_configured_value-lower_value )
                  OR ( ls_configured_value-lower_value NS ''*''
                    AND lv_value = ls_configured_value-lower_value ) ) )
              OR ( ls_configured_value-upper_value IS NOT INITIAL
                AND lv_value >= ls_configured_value-lower_value
                AND lv_value <= ls_configured_value-upper_value ).
            lv_matched = abap_true.
            EXIT.
          ENDIF.
        ENDLOOP.
        IF lv_matched = abap_false.
          result = abap_false.
          RETURN.
        ENDIF.
      ENDLOOP.
    ENDLOOP.
  ENDMETHOD.

ENDCLASS.
');`);
  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'TTYP', 'STOKESX_TAB', '$TMP', '', 'ABC', '', '', '', 'E');`);
  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'TABL', 'STOKESX', '$TMP', '', 'ABC', '', '', '', 'E');`);
