  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'CLAS', '/UI2/CL_JSON', '$TMP', '', 'ABC', '', '', '', 'E');`);
  insert.push(`INSERT INTO reposrc ('PROGNAME', 'DATA') VALUES ('/UI2/CL_JSON                            ', 'CLASS /ui2/cl_json DEFINITION PUBLIC.
  PUBLIC SECTION.

    TYPES pretty_name_mode TYPE c LENGTH 1.

    CONSTANTS: BEGIN OF pretty_mode,
                 none          TYPE pretty_name_mode VALUE '''',
                 low_case      TYPE pretty_name_mode VALUE ''L'',
                 camel_case    TYPE pretty_name_mode VALUE ''X'',
                 user          TYPE pretty_name_mode VALUE ''U'',
                 user_low_case TYPE pretty_name_mode VALUE ''C'',
               END OF pretty_mode.

    TYPES: BEGIN OF name_mapping,
             abap TYPE abap_compname,
             json TYPE string,
           END OF name_mapping.
    TYPES name_mappings TYPE HASHED TABLE OF name_mapping WITH UNIQUE KEY abap.

    TYPES bool TYPE c LENGTH 1.

    CONSTANTS: BEGIN OF c_bool,
                 true  TYPE bool VALUE \`X\`,
                 false TYPE bool VALUE \`\`,
               END OF c_bool.

    TYPES tribool TYPE c LENGTH 1.
    TYPES json TYPE string.

    CLASS-METHODS raw_to_string
      IMPORTING
        iv_xstring       TYPE xstring
      RETURNING
        VALUE(rv_string) TYPE string.

    CLASS-METHODS string_to_raw
      IMPORTING
        iv_string         TYPE string
      RETURNING
        VALUE(rv_xstring) TYPE xstring.

    CLASS-METHODS deserialize
      IMPORTING
        json             TYPE string OPTIONAL
        jsonx            TYPE xstring OPTIONAL
        pretty_name      TYPE pretty_name_mode OPTIONAL
        assoc_arrays     TYPE abap_bool OPTIONAL
        assoc_arrays_opt TYPE abap_bool OPTIONAL
        name_mappings    TYPE name_mappings OPTIONAL
        conversion_exits TYPE abap_bool OPTIONAL
      CHANGING
        data             TYPE data.

    CLASS-METHODS serialize
      IMPORTING
        data             TYPE data
        compress         TYPE abap_bool OPTIONAL
        pretty_name      TYPE pretty_name_mode OPTIONAL
        assoc_arrays     TYPE abap_bool OPTIONAL
        assoc_arrays_opt TYPE abap_bool OPTIONAL
        ts_as_iso8601    TYPE abap_bool OPTIONAL
        type_descr       TYPE REF TO cl_abap_typedescr OPTIONAL
        name_mappings    TYPE name_mappings OPTIONAL
        format_output    TYPE abap_bool OPTIONAL
      RETURNING
        VALUE(r_json)    TYPE string.

    CLASS-METHODS generate
      IMPORTING
        json           TYPE string
        pretty_name    TYPE pretty_name_mode OPTIONAL
        name_mappings  TYPE name_mappings OPTIONAL
      RETURNING
        VALUE(rr_data) TYPE REF TO data.

    METHODS serialize_int
      IMPORTING
        data          TYPE data
        name          TYPE string OPTIONAL
        type_descr    TYPE REF TO cl_abap_typedescr OPTIONAL
      RETURNING
        VALUE(r_json) TYPE string.

    METHODS deserialize_int
      IMPORTING
        json  TYPE string OPTIONAL
        jsonx TYPE xstring OPTIONAL
      CHANGING
        data  TYPE data
      RAISING
        cx_sy_move_cast_error.

    METHODS constructor
      IMPORTING
        compress      TYPE abap_bool DEFAULT abap_false
        pretty_name   TYPE pretty_name_mode DEFAULT pretty_mode-none
        assoc_arrays  TYPE abap_bool DEFAULT abap_false
        ts_as_iso8601 TYPE abap_bool DEFAULT abap_false
        name_mappings TYPE name_mappings OPTIONAL.

  PROTECTED SECTION.

    DATA mv_compress TYPE abap_bool.
    DATA mv_pretty_name TYPE pretty_name_mode.
    DATA mv_assoc_arrays TYPE abap_bool.
    DATA mv_ts_as_iso8601 TYPE abap_bool.
    DATA mv_extended TYPE abap_bool.
    DATA mt_name_mappings TYPE name_mappings.

    METHODS is_compressable
      IMPORTING
        type_descr       TYPE REF TO cl_abap_typedescr
        name             TYPE string
      RETURNING
      VALUE(rv_compress) TYPE abap_bool.

    " maps an ABAP component name to its JSON representation
    CLASS-METHODS format_name
      IMPORTING
        name           TYPE string
        pretty_name    TYPE pretty_name_mode
        name_mappings  TYPE name_mappings OPTIONAL
      RETURNING
        VALUE(rv_name) TYPE string.

    " the presence of name mappings implies the "user" pretty name modes
    CLASS-METHODS adjust_pretty_name
      IMPORTING
        pretty_name    TYPE pretty_name_mode
        name_mappings  TYPE name_mappings
      RETURNING
        VALUE(rv_mode) TYPE pretty_name_mode.

    " the ABAP names of the mappings are case insensitive
    CLASS-METHODS upper_case_mappings
      IMPORTING
        name_mappings    TYPE name_mappings
      RETURNING
        VALUE(rt_result) TYPE name_mappings.

  PRIVATE SECTION.
    CLASS-DATA mo_parsed TYPE REF TO lcl_parser.
    CLASS-METHODS _deserialize
      IMPORTING
        VALUE(prefix) TYPE string
        pretty_name   TYPE pretty_name_mode
        name_mappings TYPE name_mappings
        io_type       TYPE REF TO cl_abap_typedescr
      CHANGING
        data          TYPE data.
ENDCLASS.

CLASS /ui2/cl_json IMPLEMENTATION.
  METHOD deserialize_int.
    ASSERT 1 = ''todo''.
  ENDMETHOD.

  METHOD raw_to_string.
    rv_string = cl_abap_codepage=>convert_from( iv_xstring ).
  ENDMETHOD.

  METHOD string_to_raw.
    rv_xstring = cl_abap_codepage=>convert_to( iv_string ).
  ENDMETHOD.

  METHOD serialize_int.

    DATA lo_type        TYPE REF TO cl_abap_typedescr.
    DATA lo_struct      TYPE REF TO cl_abap_structdescr.
    DATA lo_table       TYPE REF TO cl_abap_tabledescr.
    DATA lo_objectdescr TYPE REF TO cl_abap_objectdescr.
    DATA lo_refdescr    TYPE REF TO cl_abap_refdescr.
    DATA lt_components  TYPE cl_abap_structdescr=>component_table.
    DATA ref            TYPE REF TO data.
    DATA ls_attribute   TYPE LINE OF abap_attrdescr_tab.
    DATA lv_index       TYPE i.

    FIELD-SYMBOLS <ls_component> LIKE LINE OF lt_components.
    FIELD-SYMBOLS <any> TYPE any.
    FIELD-SYMBOLS <tab> TYPE ANY TABLE.

    ASSERT name IS INITIAL. " todo

    IF type_descr IS INITIAL.
      lo_type = cl_abap_typedescr=>describe_by_data( data ).
    ELSE.
      lo_type = type_descr.
    ENDIF.

*    WRITE / |{ lo_type->kind } { lo_type->type_kind }|.

    CASE lo_type->kind.
      WHEN cl_abap_typedescr=>kind_elem.
*        WRITE ''@KERNEL console.dir(lo_type);''.
        CASE lo_type->type_kind.
          WHEN cl_abap_typedescr=>typekind_char.
            IF lo_type->absolute_name = \`\\TYPE-POOL=ABAP\\TYPE=ABAP_BOOL\`.
              IF data = abap_true.
                r_json = ''true''.
              ELSE.
                r_json = ''false''.
              ENDIF.
            ELSEIF data IS INITIAL.
              r_json = ''""''.
            ELSE.
              r_json = ''"'' && escape( val    = |{ data }|
                                      format = cl_abap_format=>e_json_string )  && ''"''.
            ENDIF.
          WHEN cl_abap_typedescr=>typekind_xstring.
            r_json = ''"'' && cl_http_utility=>encode_x_base64( data ) && ''"''.
          WHEN cl_abap_typedescr=>typekind_string.
            r_json = ''"'' && escape( val    = data
                                    format = cl_abap_format=>e_json_string ) && ''"''.
          WHEN cl_abap_typedescr=>typekind_int.
            r_json = |{ data }|.
          WHEN cl_abap_typedescr=>typekind_num.
            IF data = 0.
              r_json = |0|.
            ELSE.
              r_json = |{ data }|.
              SHIFT r_json LEFT DELETING LEADING ''0''.
            ENDIF.
          WHEN cl_abap_typedescr=>typekind_packed.
            IF mv_ts_as_iso8601 = abap_true
                AND ( lo_type->absolute_name = \`\\TYPE=TIMESTAMP\`
                OR lo_type->absolute_name = \`\\TYPE=TIMESTAMPL\` ).
              IF data IS INITIAL.
                r_json = |""|.
              ELSEIF lo_type->absolute_name = \`\\TYPE=TIMESTAMP\`.
                r_json = |"{ data TIMESTAMP = ISO }.0000000Z"|.
              ELSE.
                r_json = |"{ data TIMESTAMP = ISO }Z"|.
                REPLACE '','' IN r_json WITH ''.''.
              ENDIF.
            ELSE.
              r_json = |{ data }|.
            ENDIF.
          WHEN cl_abap_typedescr=>typekind_date.
            r_json = |"{ data DATE = ISO }"|.
          WHEN cl_abap_typedescr=>typekind_time.
            r_json = |"{ data TIME = ISO }"|.
          WHEN OTHERS.
            r_json = data.
        ENDCASE.
      WHEN cl_abap_typedescr=>kind_table.
        r_json = ''[''.
        ASSIGN data TO <tab>.
        lo_table ?= lo_type.
        LOOP AT <tab> ASSIGNING <any>.
          lv_index = sy-tabix.
          r_json = r_json && serialize_int(
            data       = <any>
            type_descr = lo_table->get_table_line_type( ) ).

          IF lines( <tab> ) <> lv_index.
            r_json = r_json && '',''.
          ENDIF.
        ENDLOOP.
        r_json = r_json && '']''.
      WHEN cl_abap_typedescr=>kind_struct.
        lo_struct ?= lo_type.
        lt_components = lo_struct->get_components( ).
        r_json = ''{''.
        LOOP AT lt_components ASSIGNING <ls_component>.
          ASSIGN COMPONENT <ls_component>-name OF STRUCTURE data TO <any>.
          ASSERT sy-subrc = 0.
          IF mv_compress = abap_true AND <any> IS INITIAL.
            CONTINUE.
          ENDIF.
          r_json = r_json && |"{ format_name( name          = |{ <ls_component>-name }|
                                              pretty_name   = mv_pretty_name
                                              name_mappings = mt_name_mappings ) }":|.
          r_json = r_json && serialize_int(
            data       = <any>
            type_descr = <ls_component>-type ).
          r_json = r_json && '',''.
        ENDLOOP.
        IF r_json CP ''*,''.
          r_json = substring( val = r_json
                              off = 0
                              len = strlen( r_json ) - 1 ).
        ENDIF.
        r_json = r_json && ''}''.
      WHEN cl_abap_typedescr=>kind_ref.
        IF data IS INITIAL.
          r_json = ''null''.
          RETURN.
        ENDIF.

        CASE lo_type->type_kind.
          WHEN cl_abap_typedescr=>typekind_iref.
            ASSERT 1 = ''todo, ref to interface''.
          WHEN cl_abap_typedescr=>typekind_oref.
            lo_refdescr ?= lo_type.
            lo_type = lo_refdescr->get_referenced_type( ).
            lo_objectdescr ?= lo_type.

            r_json = ''{''.
            LOOP AT lo_objectdescr->attributes INTO ls_attribute.
              ASSIGN data->(ls_attribute-name) TO <any>.
              ASSERT sy-subrc = 0.
              IF mv_compress = abap_true AND <any> IS INITIAL.
                CONTINUE.
              ENDIF.
              r_json = r_json && |"{ format_name( name          = |{ ls_attribute-name }|
                                                  pretty_name   = mv_pretty_name
                                                  name_mappings = mt_name_mappings ) }":|.
              r_json = r_json && serialize_int( <any> ).
              r_json = r_json && '',''.
            ENDLOOP.
            IF r_json CP ''*,''.
              r_json = substring( val = r_json
                                  off = 0
                                  len = strlen( r_json ) - 1 ).
            ENDIF.
            r_json = r_json && ''}''.
          WHEN OTHERS.
            ASSIGN data->* TO <any>.
            r_json = serialize_int( data = <any> ).
        ENDCASE.
      WHEN OTHERS.
        ASSERT 1 = ''cl_json, unknown kind''.
    ENDCASE.
  ENDMETHOD.

  METHOD deserialize.

    DATA lo_type         TYPE REF TO cl_abap_typedescr.
    DATA lt_mappings     TYPE name_mappings.
    DATA lv_pretty_name  TYPE pretty_name_mode.

    CREATE OBJECT mo_parsed.

    IF jsonx IS NOT INITIAL.
      mo_parsed->parse( cl_abap_codepage=>convert_from( jsonx ) ).
    ELSEIF json IS INITIAL.
      RETURN.
    ELSE.
      mo_parsed->parse( json ).
    ENDIF.

* todo, this should take the "pretty_name" into account
    mo_parsed->adjust_names( ).

    lo_type = cl_abap_typedescr=>describe_by_data( data ).

    lt_mappings = upper_case_mappings( name_mappings ).
    lv_pretty_name = adjust_pretty_name( pretty_name   = pretty_name
                                         name_mappings = lt_mappings ).

    _deserialize(
      EXPORTING
        prefix        = ''''
        pretty_name   = lv_pretty_name
        name_mappings = lt_mappings
        io_type       = lo_type
      CHANGING
        data          = data ).

  ENDMETHOD.

  METHOD constructor.

    DATA rtti TYPE REF TO cl_abap_classdescr.

    mv_compress        = compress.
    mv_assoc_arrays    = assoc_arrays.
    mv_ts_as_iso8601   = ts_as_iso8601.
    mt_name_mappings   = upper_case_mappings( name_mappings ).
    mv_pretty_name     = adjust_pretty_name( pretty_name   = pretty_name
                                             name_mappings = mt_name_mappings ).

*  rtti ?= cl_abap_classdescr=>describe_by_object_ref( me ).
*  IF rtti->absolute_name NE mc_me_type.
*    mv_extended = abap_true.
*  ENDIF.

  ENDMETHOD.

  METHOD is_compressable.
    rv_compress = abap_true.
  ENDMETHOD.

  METHOD upper_case_mappings.
    DATA ls_mapping LIKE LINE OF name_mappings.

    LOOP AT name_mappings INTO ls_mapping.
      TRANSLATE ls_mapping-abap TO UPPER CASE.
      INSERT ls_mapping INTO TABLE rt_result.
    ENDLOOP.
  ENDMETHOD.

  METHOD adjust_pretty_name.
    rv_mode = pretty_name.

    IF name_mappings IS INITIAL.
      RETURN.
    ENDIF.

    IF rv_mode = pretty_mode-none.
      rv_mode = pretty_mode-user.
    ELSEIF rv_mode = pretty_mode-low_case.
      rv_mode = pretty_mode-user_low_case.
    ENDIF.
  ENDMETHOD.

  METHOD format_name.
    DATA ls_mapping LIKE LINE OF name_mappings.

    CASE pretty_name.
      WHEN pretty_mode-user OR pretty_mode-user_low_case OR pretty_mode-camel_case.
        READ TABLE name_mappings INTO ls_mapping WITH TABLE KEY abap = to_upper( name ).
        IF sy-subrc = 0.
          rv_name = ls_mapping-json.
          RETURN.
        ENDIF.
    ENDCASE.

    CASE pretty_name.
      WHEN pretty_mode-camel_case.
        rv_name = to_mixed( to_lower( name ) ).
      WHEN pretty_mode-low_case OR pretty_mode-user_low_case.
        rv_name = to_lower( name ).
      WHEN OTHERS.
        rv_name = name.
    ENDCASE.
  ENDMETHOD.

  METHOD generate.
    ASSERT 1 = ''todo''.
  ENDMETHOD.

  METHOD serialize.

    DATA lo_json  TYPE REF TO /ui2/cl_json.

    ASSERT format_output IS INITIAL.

    CREATE OBJECT lo_json
      EXPORTING
        compress      = compress
        pretty_name   = pretty_name
        assoc_arrays  = assoc_arrays
        ts_as_iso8601 = ts_as_iso8601
        name_mappings = name_mappings.

    r_json = lo_json->serialize_int(
      data       = data
      type_descr = type_descr ).

  ENDMETHOD.

  METHOD _deserialize.
    DATA lo_struct     TYPE REF TO cl_abap_structdescr.
    DATA lo_table      TYPE REF TO cl_abap_tabledescr.
    DATA lo_refdescr   TYPE REF TO cl_abap_refdescr.
    DATA lt_components TYPE cl_abap_structdescr=>component_table.
    DATA ls_component  LIKE LINE OF lt_components.
    DATA lt_members    TYPE string_table.
    DATA ref           TYPE REF TO data.
    DATA lv_name       TYPE string.
    DATA lv_type       TYPE string.
    DATA lv_value      TYPE string.
    DATA lv_member     LIKE LINE OF lt_members.

    FIELD-SYMBOLS <any> TYPE any.
    FIELD-SYMBOLS <at> TYPE ANY TABLE.
    FIELD-SYMBOLS <ls_component> LIKE LINE OF lt_components.

    prefix = mo_parsed->find_ignore_case( prefix ).
*    WRITE ''@KERNEL console.dir(io_type.get());''.
    CASE io_type->kind.
      WHEN cl_abap_typedescr=>kind_elem.
*        WRITE ''@KERNEL console.dir(lo_type.get().absolute_name);''.
        IF io_type->absolute_name = ''\\TYPE-POOL=ABAP\\TYPE=ABAP_BOOL''
            OR io_type->absolute_name = ''\\TYPE=ABAP_BOOLEAN''
            OR io_type->absolute_name = ''\\TYPE=FLAG''.
          data = boolc( mo_parsed->value_string( prefix ) = ''true'' ).
        ELSEIF io_type->absolute_name = \`\\TYPE=TIMESTAMP\`
            OR io_type->absolute_name = \`\\TYPE=TIMESTAMPL\`.
          lv_value = mo_parsed->value_string( prefix ).
          REPLACE ALL OCCURRENCES OF ''-'' IN lv_value WITH ''''.
          REPLACE ALL OCCURRENCES OF ''T'' IN lv_value WITH ''''.
          REPLACE ALL OCCURRENCES OF '':'' IN lv_value WITH ''''.
          REPLACE ALL OCCURRENCES OF ''Z'' IN lv_value WITH ''''.
          data = lv_value.
        ELSEIF io_type->type_kind = cl_abap_typedescr=>typekind_date.
          lv_value = mo_parsed->value_string( prefix ).
          REPLACE ALL OCCURRENCES OF ''-'' IN lv_value WITH ''''.
          IF lv_value CO space.
            CLEAR data.
          ELSE.
            data = lv_value.
          ENDIF.
        ELSEIF io_type->type_kind = cl_abap_typedescr=>typekind_xstring.
          data = cl_http_utility=>decode_x_base64( mo_parsed->value_string( prefix ) ).
        ELSEIF io_type->type_kind = cl_abap_typedescr=>typekind_time.
          lv_value = mo_parsed->value_string( prefix ).
          REPLACE ALL OCCURRENCES OF '':'' IN lv_value WITH ''''.
          IF lv_value CO space.
            CLEAR data.
          ELSE.
            data = lv_value.
          ENDIF.
        ELSE.
          data = mo_parsed->value_string( prefix ).
        ENDIF.
      WHEN cl_abap_typedescr=>kind_table.
        lo_table ?= io_type.
        IF mo_parsed->get_type( prefix && ''/'' ) <> ''array''.
          RETURN.
        ENDIF.
        lt_members = mo_parsed->members( prefix && ''/'' ).
        ASSIGN data TO <at>.
        LOOP AT lt_members INTO lv_member.
*          WRITE ''@KERNEL console.dir(lv_member.get());''.
          CREATE DATA ref LIKE LINE OF data.
          ASSIGN ref->* TO <any>.
          _deserialize(
            EXPORTING
              prefix        = prefix && ''/'' && lv_member
              pretty_name   = pretty_name
              name_mappings = name_mappings
              io_type       = lo_table->get_table_line_type( )
            CHANGING
              data          = <any> ).
*          WRITE ''@KERNEL console.dir(fs_row_);''.
          INSERT <any> INTO TABLE <at>.
        ENDLOOP.
      WHEN cl_abap_typedescr=>kind_struct.
        lo_struct ?= io_type.
        lt_components = lo_struct->get_components( ).
        LOOP AT lt_components ASSIGNING <ls_component>.
          ASSIGN COMPONENT <ls_component>-name OF STRUCTURE data TO <any>.
          ASSERT sy-subrc = 0.
          lv_name = format_name( name          = |{ <ls_component>-name }|
                                 pretty_name   = pretty_name
                                 name_mappings = name_mappings ).
          " the parser normalizes hyphens, so mapped names must be normalized too
          REPLACE ALL OCCURRENCES OF ''-'' IN lv_name WITH ''_''.
          " WRITE ''@KERNEL console.dir("structure: " + lv_name.get());''.
          _deserialize(
            EXPORTING
              prefix        = prefix && ''/'' && lv_name
              pretty_name   = pretty_name
              name_mappings = name_mappings
              io_type       = <ls_component>-type
            CHANGING
              data          = <any> ).
        ENDLOOP.
      WHEN cl_abap_typedescr=>kind_ref.
        lo_refdescr ?= io_type.
        IF data IS INITIAL.
          lt_members = mo_parsed->members( prefix && ''/'' ).

*          WRITE ''@KERNEL console.dir(prefix.get());''.
          IF lines( lt_members ) = 0 AND prefix = ''''.
            RETURN.
          ENDIF.

          lv_type = mo_parsed->get_type( prefix && ''/'' ).
          IF lv_type IS INITIAL.
            lv_type = mo_parsed->get_type( prefix ).
          ENDIF.
*          WRITE ''@KERNEL console.dir("type: " + lv_type.get());''.

          IF lines( lt_members ) > 0 AND lv_type = ''object''.
            CLEAR lt_components.
            LOOP AT lt_members INTO lv_member.
*              WRITE ''@KERNEL console.dir("component: " + lv_member.get());''.
              CLEAR ls_component.
              ls_component-name = to_upper( lv_member ).
              TRANSLATE ls_component-name USING ''-_''.
              ls_component-type = cl_abap_refdescr=>get_ref_to_data( ).
              ASSERT ls_component-name IS NOT INITIAL.
              APPEND ls_component TO lt_components.
            ENDLOOP.
            lo_struct = cl_abap_structdescr=>create( lt_components ).
            CREATE DATA data TYPE HANDLE lo_struct.
          ELSEIF lv_type = ''array''.
            lo_table = cl_abap_tabledescr=>create( cl_abap_refdescr=>get_ref_to_data( ) ).
            CREATE DATA data TYPE HANDLE lo_table.
          ELSE.
            CASE lv_type.
              WHEN ''num''.
                lv_value = mo_parsed->value_string( prefix ).
                IF lv_value CO ''-0123456789''.
                  CREATE DATA data TYPE i.
                ELSEIF lv_value CO ''-0123456789.''.
                  CREATE DATA data TYPE f.
                ELSE.
                  ASSERT 1 = ''todo''.
                ENDIF.
              WHEN ''bool''.
                CREATE DATA data TYPE HANDLE cl_abap_typedescr=>describe_by_name( ''ABAP_BOOL'' ).
              WHEN ''str''.
                CREATE DATA data TYPE HANDLE cl_abap_elemdescr=>get_string( ).
              WHEN ''null''.
                CLEAR data.
                RETURN.
              " WHEN OTHERS.
              "   ASSERT 1 = ''todo''.
            ENDCASE.
          ENDIF.
        ENDIF.
        ASSIGN data->* TO <any>.
* todo: optimize, it should not be nessesary to call cl_abap_typedescr
        _deserialize(
          EXPORTING
            prefix        = prefix
            pretty_name   = pretty_name
            name_mappings = name_mappings
            io_type       = cl_abap_typedescr=>describe_by_data( <any> )
          CHANGING
            data          = <any> ).
      WHEN OTHERS.
        ASSERT 1 = ''cl_json, unknown kind''.
    ENDCASE.
  ENDMETHOD.

ENDCLASS.
');`);
