  insert.push(`INSERT INTO reposrc ('PROGNAME', 'DATA') VALUES ('CX_SQL_EXCEPTION                        ', 'CLASS cx_sql_exception DEFINITION PUBLIC INHERITING FROM cx_static_check.
  PUBLIC SECTION.
    DATA sql_message TYPE string.
    DATA sql_code TYPE i.
    DATA db_error TYPE flag.
    DATA internal_error TYPE sy-subrc.

    METHODS constructor
      IMPORTING
        textid      LIKE textid OPTIONAL
        sql_message TYPE string OPTIONAL
        sql_code    TYPE i OPTIONAL
        db_error    TYPE flag OPTIONAL
        previous    TYPE REF TO cx_root OPTIONAL.
ENDCLASS.

CLASS cx_sql_exception IMPLEMENTATION.
  METHOD constructor.
    super->constructor(
      textid   = textid
      previous = previous ).

    me->sql_message = sql_message.
    me->db_error = db_error.
    me->sql_code = sql_code.
  ENDMETHOD.

ENDCLASS.');`);
  insert.push(`INSERT INTO "tadir" ("pgmid", "object", "obj_name", "devclass", "korrnum", "srcsystem", "delflag", "genflag", "edtflag", "masterlang")
      VALUES ('R3TR', 'CLAS', 'CL_SQL_STATEMENT', '$TMP', '', 'ABC', '', '', '', 'E');`);
  insert.push(`INSERT INTO reposrc ('PROGNAME', 'DATA') VALUES ('CL_SQL_STATEMENT                        ', 'CLASS cl_sql_statement DEFINITION PUBLIC.
  PUBLIC SECTION.
    METHODS constructor
      IMPORTING
        con_ref TYPE REF TO cl_sql_connection OPTIONAL.

    METHODS execute_update
      IMPORTING
        statement           TYPE string
      RETURNING
        VALUE(rows_updated) TYPE i
      RAISING
        cx_sql_exception.

    METHODS set_param_table
      IMPORTING
        table_ref  TYPE REF TO data
        lob_fields TYPE adbc_column_tab OPTIONAL
      RAISING
        cx_parameter_invalid.

    METHODS set_param
      IMPORTING
        data_ref TYPE REF TO data
        pos      TYPE int2 DEFAULT 0
        ind_ref  TYPE REF TO int2 OPTIONAL
        inout    TYPE any OPTIONAL
        is_lob   TYPE flag DEFAULT space
      RAISING
        cx_parameter_invalid.

    METHODS execute_procedure
      IMPORTING
        proc_name             TYPE c
      RETURNING
        VALUE(rows_processed) TYPE i
      RAISING
        cx_sql_exception.

    METHODS execute_query
      IMPORTING
        statement         TYPE string
        hold_cursor       TYPE abap_bool OPTIONAL
      RETURNING
        VALUE(result_set) TYPE REF TO cl_sql_result_set
      RAISING
        cx_sql_exception.

    METHODS execute_ddl
      IMPORTING
        statement TYPE string
      RAISING
        cx_sql_exception.

  PRIVATE SECTION.
    DATA mv_connection TYPE string.
ENDCLASS.

CLASS cl_sql_statement IMPLEMENTATION.
  METHOD set_param_table.
    ASSERT 1 = ''not supported''.
  ENDMETHOD.

  METHOD set_param.
    ASSERT 1 = ''not supported''.
  ENDMETHOD.

  METHOD execute_procedure.
    ASSERT 1 = ''not supported''.
  ENDMETHOD.

  METHOD constructor.
    IF con_ref IS INITIAL.
      mv_connection = ''DEFAULT''.
    ELSE.
      mv_connection = con_ref->get_con_name( ).
    ENDIF.

    ASSERT mv_connection IS NOT INITIAL.
  ENDMETHOD.

  METHOD execute_ddl.
    ASSERT 1 = ''not supported''.
  ENDMETHOD.

  METHOD execute_update.

    DATA lv_sql_message TYPE string.
    DATA connection LIKE mv_connection.

    ASSERT statement IS NOT INITIAL.
    connection = mv_connection.

    WRITE ''@KERNEL if (abap.context.databaseConnections[connection.get()] === undefined) {''.
    lv_sql_message = ''not connected to db''.
    WRITE ''@KERNEL }''.
    IF lv_sql_message IS NOT INITIAL.
      RAISE EXCEPTION TYPE cx_sql_exception.
    ENDIF.

    WRITE ''@KERNEL try {''.
    WRITE ''@KERNEL   await abap.context.databaseConnections[connection.get()].execute(statement.get());''.
    WRITE ''@KERNEL } catch(e) {''.
    WRITE ''@KERNEL   lv_sql_message.set(e + "");''.
    WRITE ''@KERNEL }''.
    IF lv_sql_message IS NOT INITIAL.
      RAISE EXCEPTION TYPE cx_sql_exception.
    ENDIF.

  ENDMETHOD.

  METHOD execute_query.
    DATA lx_osql        TYPE REF TO cx_sy_dynamic_osql_semantics.
    DATA lv_sql_message TYPE string.

    DATA connection LIKE mv_connection.

    connection = mv_connection.

    ASSERT statement IS NOT INITIAL.
    ASSERT mv_connection IS NOT INITIAL.

    WRITE ''@KERNEL if (abap.context.databaseConnections[connection.get()] === undefined) {''.
    lv_sql_message = ''not connected to db''.
    WRITE ''@KERNEL }''.
    IF lv_sql_message IS NOT INITIAL.
      RAISE EXCEPTION TYPE cx_sql_exception EXPORTING sql_message = lv_sql_message.
    ENDIF.

    CREATE OBJECT result_set.

    TRY.
        WRITE ''@KERNEL   const res = await abap.context.databaseConnections[connection.get()].select({select: statement.get()});''.
*    WRITE ''@KERNEL   console.dir(res.rows);''.
        WRITE ''@KERNEL   result_set.get().mv_magic = res.rows;''.
      CATCH cx_sy_dynamic_osql_semantics INTO lx_osql.
        RAISE EXCEPTION TYPE cx_sql_exception EXPORTING sql_message = lx_osql->sqlmsg.
    ENDTRY.

  ENDMETHOD.

ENDCLASS.
');`);
